(()=>{
const WHATSAPP='34648515835'; // número de pedidos de la tienda
const IMG={"tardeo_mini": "data:image/webp;base64,", "pecao_mini": "data:image/webp;base64,", "excusa_mini": "data:image/webp;base64,", "confesion_mini": "data:image/webp;base64,"};
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const eur=n=>n.toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';
const store={get(k){try{return sessionStorage.getItem(k)}catch(e){return null}},set(k,v){try{sessionStorage.setItem(k,v)}catch(e){}}};

/* ---------- los vinos ---------- */
const WINES=[
 {id:'pecao',n:'El Pecao',hora:'16:00',momento:'La sobremesa',tipo:'Blanco',origen:'Cataluña',uvas:'Sauvignon Blanc y Picapoll',precio:14,
  frase:'Todos tenemos algún pecado favorito. Este, al menos, viene embotellado.',
  cata:'Un blanco fresco con más volumen y complejidad de lo normal. Profundo, elegante y con una textura que pide beber sin prisa. De los que se repiten.',
  con:'Mariscos, arroces, pescados elaborados, quesos suaves y sobremesas largas.',
  bg:'#57218D',sky:'#EFE4FA',ink:'#17081A',cap:'#6A35B0',label:'#6A35B0',nameC:'#F9D602'},
 {id:'tardeo',n:'El Tardeo',hora:'19:30',momento:'La terraza',tipo:'Blanco',origen:'Cataluña',uvas:'Macabeo, Parellada y Garnacha Blanca',precio:12,
  frase:'Fácil de disfrutar. Difícil de olvidar.',
  cata:'Aromas finos a fruta blanca, boca fresca y ligera, y un final largo y elegante. Para salir “a tomar algo” con la intención de volver pronto… y no volver.',
  con:'Tapas, terrazas, aperitivos, pescado, arroces y amigos. Convierte unas copas en una cena.',
  bg:'#DD167C',sky:'#FF8A3D',ink:'#17081A',cap:'#EC008C',label:'#EC008C',nameC:'#F9D602'},
 {id:'excusa',n:'La Excusa',hora:'21:45',momento:'El plan improvisado',tipo:'Tinto',origen:'Cataluña',uvas:'Tempranillo y Merlot',precio:12,
  frase:'Nunca fue el vino. Era la compañía.',
  cata:'Agradable y elegante, con aromas de frutos del bosque. Sabroso y fresco, con un tanino suave y una boca larga. Carácter sin complicaciones.',
  con:'Embutidos, carnes, pizzas, hamburguesas, tapas y planes de última hora.',
  bg:'#F8D402',sky:'#5E2591',ink:'#FFFFFF',cap:'#F9D602',label:'#F9D602',nameC:'#EC008C'},
 {id:'confesion',n:'La Confesión',hora:'00:30',momento:'La noche que se alarga',tipo:'Tinto',origen:'DO Jumilla',uvas:'Monastrell y Syrah',precio:15,
  frase:'Hay verdades que salen mejor con una copa delante.',
  cata:'Con cuerpo pero tremendamente goloso. Intenso, envolvente y lleno de matices. Después de la segunda copa salen las confesiones. Después de la tercera, las de verdad.',
  con:'Carnes a la brasa, guisos, quesos curados y cenas que acaban más tarde de lo previsto.',
  bg:'#98AE05',sky:'#170B1C',ink:'#FFFFFF',cap:'#9BC21A',label:'#A8C40A',nameC:'#EC008C'}
];
const W=Object.fromEntries(WINES.map(w=>[w.id,w]));
const mini=(k,cls='',bg=false)=>`<img src="${IMG[k+'_mini']}" alt="${W[k].n}" class="${cls}"${bg?` style="background:${W[k].bg}"`:''}>`;

/* ---------- puerta +18 ---------- */
const gate=$('#gate');
function openGate(){gate.classList.add('out');document.body.classList.remove('locked');store.set('ase18','1');setTimeout(()=>gate.remove(),1100)}
if(store.get('ase18')==='1'){gate.remove();document.body.classList.remove('locked')}
else{
  $('#gate-yes').onclick=openGate;
  $('#gate-no').onclick=()=>{$('#gate-msg').textContent='Pues te esperamos. Aquí seguiremos, sin prisa. 🥤'};
}

/* ---------- titular con letras vivas ---------- */
$$('[data-split]').forEach(el=>{el.innerHTML=[...el.textContent].map(c=>`<span class="ch">${c}</span>`).join('')});
const fb=$('#foot-big'); fb.innerHTML=[...fb.textContent].map((c,i)=>c===' '?' ':`<span class="c${i%4}">${c}</span>`).join('');

/* ---------- copa de la portada ---------- */
const wave=$('#wave'), liquid=$('#liquid'), stream=$('#stream'), pb=$('#pour-bottle');
let fill=0, target=.12, tilt=0, tiltT=0, phase=0, pourA=0, autoPour=.32;
function wavePath(y,ph){
  let d=`M40 ${y}`;
  for(let x=40;x<=380;x+=10){d+=` L${x} ${(y+Math.sin(x/26+ph)*4+Math.sin(x/11+ph*1.7)*1.6).toFixed(1)}`}
  return d+` L380 ${y+400} L40 ${y+400} Z`;
}
addEventListener('pointermove',e=>{tiltT=((e.clientX/innerWidth)-.5)*14},{passive:true});
function heroFrame(){
  if(scrollY>innerHeight*1.4){requestAnimationFrame(heroFrame);return}
  const p=Math.min(1,Math.max(0,scrollY/(innerHeight*.9)));
  target=Math.max(autoPour,.12+p*.78);
  fill+=(target-fill)*.05; tilt+=(tiltT-tilt)*.05; phase+=reduce?0:.05;
  const y=345-fill*215;
  wave.setAttribute('d',wavePath(y,phase));
  $('#liq-body').setAttribute('y',y+4);
  liquid.setAttribute('transform',`rotate(${tilt.toFixed(2)} 210 ${y})`);
  const pouring=target-fill>.008;
  pourA+=((pouring?1:0)-pourA)*.08;
  const rot=200+pourA*38, lift=(1-pourA)*-70;
  pb.setAttribute('transform',`translate(258 ${(64+lift).toFixed(1)}) rotate(${rot.toFixed(1)}) scale(.8)`);
  pb.style.opacity=(.3+pourA*.7).toFixed(2);
  stream.setAttribute('d',`M258 66 Q 232 ${(90+y)/2-20} 212 ${y+2}`);
  stream.style.opacity=pourA>.6?1:0;
  requestAnimationFrame(heroFrame);
}
requestAnimationFrame(heroFrame);

/* ---------- cinta ---------- */
const star='<svg viewBox="0 0 20 20"><path d="M10 0 L12.5 7.5 L20 10 L12.5 12.5 L10 20 L7.5 12.5 L0 10 L7.5 7.5Z" fill="currentColor"/></svg>';
$('#track').innerHTML=`<span>Menos normas${star}Más momentos${star}Más vida${star}Sin postureo${star}</span>`.repeat(4);

/* cinta en movimiento: se acelera al hacer scroll */
const track=$('#track'); let mx=0, lastY=scrollY, boost=0;
function marquee(){
  const half=track.scrollWidth/2, dy=Math.abs(scrollY-lastY); lastY=scrollY;
  boost=Math.min(14,boost*.9+dy*.12);
  mx-= (reduce?.35:.9)+boost; if(-mx>=half) mx+=half;
  track.style.transform=`translate3d(${mx.toFixed(1)}px,0,0)`;
  requestAnimationFrame(marquee);
}
requestAnimationFrame(marquee);

/* ---------- manifiesto ---------- */
$$('[data-reveal]').forEach(p=>{
  const out=[];
  p.childNodes.forEach(n=>{
    const s=n.nodeType!==3;
    n.textContent.split(/(\s+)/).forEach(t=>out.push(t.trim()?`<span class="wd${s?' s':''}">${t}</span>`:t));
  });
  p.innerHTML=out.join('');
});
// cada frase se enciende entera en cuanto asoma, palabra a palabra en un instante
$$('[data-reveal]').forEach(p=>p.querySelectorAll('.wd').forEach((w,i)=>w.style.transitionDelay=(i*45)+'ms'));
function revealFrame(){
  $$('[data-reveal]').forEach(p=>{if(!p.dataset.on&&p.getBoundingClientRect().top<innerHeight*.95){p.dataset.on=1;p.querySelectorAll('.wd').forEach(w=>w.classList.add('on'))}});
}

/* ---------- historia ---------- */
function bottleSVG(w){
  const dark=w.tipo==='Tinto';
  return `<g class="bottle-tilt"><g class="bottle-spin">
   <path fill="${dark?'#1C0A10':'#F2ECBF'}" stroke="#17081A" stroke-width="3" d="M84 14 H116 V40 Q118 46 118 54 V170 C118 214 168 226 168 284 V586 Q168 608 146 608 H54 Q32 608 32 586 V284 C32 226 82 214 82 170 V54 Q82 46 84 40 Z"/>
   ${dark?'':'<path fill="#FBF8E6" d="M86 104 H114 V170 C114 196 128 206 138 214 H62 C72 206 86 196 86 170 Z"/>'}
   <rect x="80" y="8" width="40" height="96" fill="${w.cap}" stroke="#17081A" stroke-width="3"/>
   <path d="M82 22 H118 M82 32 H118 M82 42 H118 M82 52 H118" stroke="#17081A" stroke-width="1.5" opacity=".28"/>
   <rect x="44" y="300" width="18" height="290" rx="9" fill="#fff" opacity="${dark?.16:.45}"/>
   <rect x="34" y="332" width="132" height="208" fill="${w.label}" stroke="#17081A" stroke-width="3"/>
   <g transform="rotate(-12 96 408)" style="font-family:Anton,Impact,sans-serif" text-anchor="middle">
    <text x="99" y="382" font-size="36" fill="${w.nameC}">AQUÍ</text><text x="96" y="379" font-size="36" fill="#17081A">AQUÍ</text>
    <text x="93" y="420" font-size="36" fill="${w.nameC}">SE</text><text x="90" y="417" font-size="36" fill="#17081A">SE</text>
    <text x="101" y="458" font-size="36" fill="${w.nameC}">BEBE</text><text x="98" y="455" font-size="36" fill="#17081A">BEBE</text>
   </g>
   <path d="M136 404 h16 c0 14 -4 20 -8 21 v12 h6 M144 437 h-6" stroke="#17081A" stroke-width="2.5" fill="none"/>
   <text x="100" y="512" text-anchor="middle" style="font-family:Anton,Impact,sans-serif" font-size="${w.n.length>10?20:23}" fill="${w.nameC}">${w.n.toUpperCase()}</text>
  </g></g>`;
}
$('#chapters').innerHTML=WINES.map((w,i)=>{const [art,...rest]=w.n.split(' ');return `
 <article class="chap" data-i="${i}" id="vino-${w.id}">
  <div class="card">
   <span class="hora">${w.hora} · ${w.momento}</span>
   <h3><i>${art}</i> ${rest.join(' ')}</h3>
   <p class="frase">“${w.frase}”</p>
   <button class="more-btn" aria-expanded="false">Cata y maridaje <b>+</b></button>
   <div class="more"><div><p class="cata">${w.cata}</p>
   <dl><dt>Uvas</dt><dd>${w.uvas}</dd><dt>Origen</dt><dd>${w.tipo} · ${w.origen}</dd><dt>Va con</dt><dd>${w.con}</dd></dl></div></div>
   <div class="buy"><span class="price">${eur(w.precio)}</span><button class="add" data-add="${w.id}">Añadir al pedido +</button></div>
  </div>
 </article>`}).join('');
$('#dots').innerHTML=WINES.map((w,i)=>`<button aria-label="${w.n}" data-go="${i}"></button>`).join('');
$$('[data-go]').forEach(b=>b.onclick=()=>$$('.chap')[+b.dataset.go].scrollIntoView({behavior:'smooth',block:'center'}));
const bottle=$('#bottle'), story=$('#vinos'), reloj=$('#reloj');
let cur=-1;
function setWine(i){
  if(i===cur) return;
  const first=cur===-1; cur=i; const w=WINES[i];
  if(first||reduce){bottle.innerHTML=bottleSVG(w)}
  else{
    const sp=bottle.querySelector('.bottle-spin'); sp.classList.remove('swapin'); void sp.getBoundingClientRect(); sp.classList.add('swap');
    setTimeout(()=>{if(cur!==i)return;bottle.innerHTML=bottleSVG(w);bottle.querySelector('.bottle-spin').classList.add('swapin')},250);
  }
  reloj.textContent=w.hora;
  story.style.color=w.ink;
  story.style.setProperty('--bgc',w.sky); story.style.setProperty('--ink',w.ink);
  $$('#dots button').forEach((d,k)=>d.classList.toggle('on',k===i));
}
const hex=h=>[1,3,5].map(k=>parseInt(h.slice(k,k+2),16));
const mix=(a,b,t)=>{const A=hex(a),B=hex(b);return `rgb(${A.map((v,k)=>Math.round(v+(B[k]-v)*t)).join(',')})`};
function storyFrame(){
  const chs=$$('.chap'), mid=innerHeight/2; let best=0,bd=1e9; const centers=[];
  chs.forEach((c,i)=>{const r=c.getBoundingClientRect(),cc=r.top+r.height/2;centers.push(cc);const d=Math.abs(cc-mid);if(d<bd){bd=d;best=i}});
  setWine(best);
  let i=0; while(i<centers.length-1&&centers[i+1]<mid) i++;
  let t=i<centers.length-1?Math.min(1,Math.max(0,(mid-centers[i])/(centers[i+1]-centers[i]))):0;
  if(centers[0]>mid){i=0;t=0}
  story.style.background=i<WINES.length-1?mix(WINES[i].sky,WINES[i+1].sky,t):WINES[i].sky;
  const tl=bottle.querySelector('.bottle-tilt');
  if(tl&&!reduce) tl.style.transform=`rotate(${(Math.sin(scrollY/240)*3).toFixed(2)}deg)`;
}

/* ---------- móvil: plegables y pestaña activa ---------- */
document.addEventListener('click',e=>{const b=e.target.closest('.more-btn');if(!b)return;const c=b.closest('.card');const o=c.classList.toggle('open');b.setAttribute('aria-expanded',o)});
const tabs=$$('.tabbar a');
if('IntersectionObserver' in window){
  const io=new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting)tabs.forEach(t=>t.classList.toggle('on',t.dataset.tab===en.target.id))}),{rootMargin:'-45% 0px -50% 0px'});
  ['vinos','quiz','pack','top','motivo','manifiesto'].forEach(id=>{const el=document.getElementById(id);if(el)io.observe(el)});
}

/* ---------- carrito ---------- */
let cart={}, packs=[];
try{const s=JSON.parse(store.get('ase-cart')||'null');if(s&&typeof s==='object'){
  Object.entries(s.cart||{}).forEach(([k,q])=>{q=Math.floor(+q);if(W[k]&&q>0&&q<100)cart[k]=q});
  packs=(Array.isArray(s.packs)?s.packs:[]).filter(p=>p&&Array.isArray(p.items)&&p.items.length&&p.items.every(k=>W[k])).map(p=>({items:p.items.slice(0,6)}));
}}catch(e){cart={};packs=[]}
const save=()=>store.set('ase-cart',JSON.stringify({cart,packs}));
const count=()=>Object.values(cart).reduce((a,b)=>a+b,0)+packs.length;
const psum=p=>p.items.reduce((a,k)=>a+W[k].precio,0);
const total=()=>Object.entries(cart).reduce((s,[k,q])=>s+W[k].precio*q,0)+packs.reduce((s,p)=>s+psum(p),0);
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('on'),2200)}
function bump(){['#cart-open','#cart-open-2'].forEach(s=>{const b=$(s);b.classList.remove('bump');void b.offsetWidth;b.classList.add('bump')});try{navigator.vibrate&&navigator.vibrate(18)}catch(e){}}
function add(id){cart[id]=(cart[id]||0)+1;save();renderCart();bump();toast(`${W[id].n} al pedido 🍷`)}
const summarize=items=>{const c={};items.forEach(k=>c[k]=(c[k]||0)+1);return Object.entries(c).map(([k,q])=>`${q}× ${W[k].n}`).join(', ')};
function renderCart(){
  $('#cart-n').textContent=count(); $('#cart-n2').textContent=count();
  const rows=Object.entries(cart).filter(([,q])=>q>0).map(([k,q])=>`
   <div class="line">${mini(k,'',true)}<div><b>${W[k].n}</b><small>${eur(W[k].precio)} · ${W[k].tipo}</small></div>
   <div class="qty"><button data-q="${k}" data-d="-1" aria-label="Quitar uno">−</button><span>${q}</span><button data-q="${k}" data-d="1" aria-label="Añadir uno">+</button></div></div>`);
  packs.forEach((p,i)=>rows.push(`<div class="line">${mini(p.items[0],'',true)}<div><b>Pack de ${p.items.length}</b><small>${summarize(p.items)} · ${eur(psum(p))}</small></div>
    <div class="qty"><button data-rp="${i}" aria-label="Quitar pack">✕</button></div></div>`));
  $('#lines').innerHTML=rows.length?rows.join(''):`<div class="empty-c"><p>Aquí todavía<br>no se bebe nada</p>Añade una botella o monta tu pack.</div>`;
  $('#tot').textContent=eur(total());
  const wa=$('#wa'); wa.setAttribute('aria-disabled',count()?'false':'true'); wa.href=waLink();
}
function waLink(){
  const name=$('#c-name').value.trim();
  let t=`¡Hola, AQUÍ SE BEBE! 🍷${name?` Soy ${name}.`:''} Quiero hacer este pedido:\n`;
  Object.entries(cart).filter(([,q])=>q>0).forEach(([k,q])=>t+=`\n• ${q} × ${W[k].n} (${eur(W[k].precio)})`);
  packs.forEach(p=>t+=`\n• Pack de ${p.items.length}: ${summarize(p.items)}`);
  t+=`\n\nTotal orientativo: ${eur(total())}\n¿Me confirmáis envío y pago?`;
  return 'https://wa.me/'+WHATSAPP+'?text='+encodeURIComponent(t);
}
document.addEventListener('click',e=>{
  const a=e.target.closest('[data-add]'); if(a){add(a.dataset.add);return}
  const q=e.target.closest('[data-q]'); if(q){const k=q.dataset.q;cart[k]=Math.max(0,(cart[k]||0)+(+q.dataset.d));if(!cart[k])delete cart[k];save();renderCart();return}
  const rp=e.target.closest('[data-rp]'); if(rp){packs.splice(+rp.dataset.rp,1);save();renderCart()}
});
$('#c-name').addEventListener('input',()=>$('#wa').href=waLink());
const drawer=$('#drawer'),veil=$('#veil');
function openCart(o){drawer.classList.toggle('on',o);veil.classList.toggle('on',o);drawer.setAttribute('aria-hidden',!o);if(o)$('#cart-close').focus()}
$('#cart-open').onclick=()=>openCart(true);$('#cart-open-2').onclick=()=>openCart(true);$('#cart-close').onclick=()=>openCart(false);veil.onclick=()=>openCart(false);
addEventListener('keydown',e=>{if(e.key==='Escape')openCart(false)});
renderCart();

/* ---------- quiz ---------- */
const QS=[
 {q:'¿Dónde te pilla el momento?',o:[['☀️','En una terraza al sol',{tardeo:2,pecao:1}],['🍽️','En una sobremesa que no acaba',{pecao:2}],['📲','En un plan que surgió hace diez minutos',{excusa:2}],['🌙','En una cena que se está alargando',{confesion:2}]]},
 {q:'¿Qué hay encima de la mesa?',o:[['🦐','Marisco o un arroz',{pecao:2,tardeo:1}],['🫒','Tapas y aperitivo',{tardeo:2,excusa:1}],['🍕','Pizza, burger o embutido',{excusa:2}],['🥩','Brasa o queso curado',{confesion:2}]]},
 {q:'¿Y cómo te apetece?',o:[['🧊','Fresco y ligero',{tardeo:2}],['✨','Fresco, pero con fondo',{pecao:2}],['🍒','Afrutado y fácil',{excusa:2}],['🔥','Con cuerpo y goloso',{confesion:2}]]}
];
let qi=0, score={};
function renderQ(){
  const box=$('#qbox');
  const prog=`<div class="q-prog">${QS.map((_,i)=>`<i class="${i<qi?'on':''}"></i>`).join('')}</div>`;
  if(qi<QS.length){
    const s=QS[qi];
    box.innerHTML=prog+`<div class="q-step"><h3>${s.q}</h3><div class="opts">${s.o.map((o,i)=>`<button class="opt" data-o="${i}"><span class="e">${o[0]}</span><b>${o[1]}</b></button>`).join('')}</div></div>`;
    box.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{Object.entries(s.o[+b.dataset.o][2]).forEach(([k,v])=>score[k]=(score[k]||0)+v);qi++;renderQ()});
  } else {
    const best=WINES.slice().sort((a,b)=>(score[b.id]||0)-(score[a.id]||0))[0];
    box.innerHTML=prog+`<div class="q-step res"><div class="res-pic" style="background:${best.bg}">${mini(best.id)}</div><div>
      <span class="k">Hoy te toca</span><h3>${best.n}</h3>
      <p class="fr">“${best.frase}”</p><p>${best.cata}</p>
      <div class="row"><button class="btn am" data-add="${best.id}">Añadir · ${eur(best.precio)}</button><a class="btn" href="#vino-${best.id}">Ver su momento</a><button class="btn" id="q-again">Repetir</button></div></div></div>`;
    $('#q-again').onclick=()=>{qi=0;score={};renderQ()};
  }
}
renderQ();

/* ---------- motivos ---------- */
const MOTIVOS=[
 ['Es martes. Y eso ya es bastante.','excusa'],['Ha salido el sol (por fin).','tardeo'],['Han venido los de siempre.','excusa'],
 ['La comida ha estado tan buena que nadie se levanta.','pecao'],['Te han dicho que sí.','confesion'],['No ha pasado nada. Celébralo.','tardeo'],
 ['Por fin es viernes. O casi.','tardeo'],['Tienes algo que contar y no sabes por dónde empezar.','confesion'],['El arroz ya está en la mesa.','pecao'],
 ['Alguien ha dicho “una y nos vamos”.','excusa'],['La conversación se está poniendo interesante.','confesion'],['Hay queso. Siempre que hay queso.','pecao'],
 ['Has sobrevivido al lunes.','excusa'],['Empieza la tarde y no hay prisa.','tardeo'],['Hace tiempo que no os veíais.','confesion']
];
let last=-1;
$('#motivo-btn').onclick=e=>{
  let i; do{i=Math.floor(Math.random()*MOTIVOS.length)}while(i===last); last=i;
  const [m,w]=MOTIVOS[i], v=W[w];
  $('#motivo-card').innerHTML=`<span>${m}</span>`;
  $('#motivo-sug').innerHTML=`Para eso: <a href="#vino-${v.id}">${v.n}</a> · <button data-add="${v.id}">añadir al pedido</button>`;
  if(!reduce) corks(e.currentTarget);
};
function corks(btn){
  const r=btn.getBoundingClientRect(), sec=$('#motivo'), sr=sec.getBoundingClientRect();
  const cols=['#F9D602','#5A2391','#98AE05','#FFFFFF'];
  for(let k=0;k<9;k++){
    const c=document.createElement('i'); c.className='cork'; c.style.background=cols[k%4];
    c.style.left=(r.left-sr.left+r.width/2)+'px'; c.style.top=(r.top-sr.top)+'px'; sec.appendChild(c);
    const dx=(Math.random()-.5)*700, dy=-200-Math.random()*320, rot=(Math.random()-.5)*720;
    c.animate([{transform:'translate(0,0) rotate(0)'},{transform:`translate(${dx}px,${dy}px) rotate(${rot}deg)`,offset:.6},{transform:`translate(${dx*1.2}px,${dy+520}px) rotate(${rot*1.4}deg)`,opacity:0}],{duration:1400,easing:'cubic-bezier(.2,.7,.4,1)'}).onfinish=()=>c.remove();
  }
}

/* ---------- pack ---------- */
let size=3, slots=[];
$('#chips').innerHTML=WINES.map(w=>`<button class="chip" data-pk="${w.id}" style="--c:${w.bg};--ci:${w.ink}">${mini(w.id)}<span><b>${w.n}</b><small>${w.tipo} · ${eur(w.precio)}</small></span></button>`).join('');
$$('.size button').forEach(b=>b.onclick=()=>{size=+b.dataset.size;$$('.size button').forEach(x=>x.setAttribute('aria-pressed',x===b));slots=slots.slice(0,size);renderPack()});
$$('[data-pk]').forEach(b=>b.onclick=()=>{if(slots.length>=size){toast('La caja está llena. Quita una o pásate al de 6 😉');return}slots.push(b.dataset.pk);renderPack(true)});
function renderPack(dropLast){
  const el=$('#slots'); el.className='slots s'+size;
  el.innerHTML=Array.from({length:size},(_,i)=>{const k=slots[i];
    return k?`<div class="slot" style="background:${W[k].bg}">${mini(k,dropLast&&i===slots.length-1?'':'still')}<button class="x" data-rm="${i}" aria-label="Quitar">×</button></div>`:`<div class="slot empty"></div>`}).join('');
  el.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{slots.splice(+b.dataset.rm,1);renderPack()});
  const sum=slots.reduce((a,k)=>a+W[k].precio,0);
  $('#pack-t').innerHTML=`${slots.length} de ${size} botellas<b>${eur(sum)}</b>`;
  $('#pack-add').disabled=slots.length!==size;
}
$('#pack-add').onclick=()=>{packs.push({items:slots.slice()});slots=[];save();renderPack();renderCart();bump();toast(`Pack de ${size} al pedido 📦`)};
renderPack();

/* ---------- boletín ---------- */
$('#news').addEventListener('submit',e=>{
  e.preventDefault(); const m=$('#news-mail').value.trim();
  const url='https://wa.me/'+WHATSAPP+'?text='+encodeURIComponent(`¡Hola! Quiero apuntarme a los descuentos y eventos de AQUÍ SE BEBE. Mi correo: ${m}`);
  $('#news-msg').innerHTML=`Un paso más: <a href="${url}" target="_blank" rel="noopener">envíanoslo por WhatsApp</a> y quedas dentro.`;
});

/* ---------- scroll ---------- */
function banda(){const bi=$('#banda-img'), br=bi.parentElement.getBoundingClientRect();
  if(!reduce&&br.top<innerHeight&&br.bottom>0) bi.style.transform=`translateY(${((br.top/innerHeight)*-5).toFixed(2)}%)`}
let ticking=false;
function onScroll(){document.body.classList.toggle('at-top',scrollY<innerHeight*.55);if(ticking)return;ticking=true;requestAnimationFrame(()=>{revealFrame();storyFrame();banda();ticking=false})}
addEventListener('scroll',onScroll,{passive:true});addEventListener('resize',onScroll);
setWine(0);document.body.classList.toggle('at-top',scrollY<innerHeight*.55);onScroll();
})();
